import type { EmbeddingInput } from '@theoremjs/agents';

/** A document an embedding preview starts with, and the file it came from. */
export type ExampleEmbeddingFile = { input: EmbeddingInput; from: string };

const png = (from: string, data: string): ExampleEmbeddingFile => ({
  from,
  input: { parts: [{ type: 'media', mimeType: 'image/png', data }] },
});

/** The refund policy, as a text file: its paragraphs are documents of their own. */
const REFUND_POLICY = [
  'Refunds are available within 14 days of a charge, in full and to the original card.',
  'After 14 days a refund is made as credit toward the next invoice, not as money back.',
  'Refunds take five to ten working days to reach your bank, depending on the card issuer.',
];

/**
 * The files an embedding preview starts with, beside the example text: three pictures that
 * belong to its topics, and a refund policy that adds three documents to billing.
 */
export const EXAMPLE_EMBEDDING_FILES: readonly ExampleEmbeddingFile[] = [
  ...REFUND_POLICY.map((text) => ({ input: text, from: 'refund-policy.md' })),
  png(
    'empty-trash-dialog.png',
    '',
  ),
  png(
    'desktop-stacks.png',
    '',
  ),
  png(
    'lisbon-tram-28.png',
    '',
  ),
];
